import com.thoughtworks.xstream.XStream;
import com.thoughtworks.xstream.converters.Converter;
import com.thoughtworks.xstream.converters.MarshallingContext;
import com.thoughtworks.xstream.converters.UnmarshallingContext;
import com.thoughtworks.xstream.io.HierarchicalStreamReader;
import com.thoughtworks.xstream.io.HierarchicalStreamWriter;

public class MyClass {

    public static class Position {
        private String title;
        private String startDate;
        private String endDate;

        public String getTitle() { return title; }
        public void setTitle(String title) { this.title = title; }
        public String getStartDate() { return startDate; }
        public void setStartDate(String startDate) { this.startDate = startDate; }
        public String getEndDate() { return endDate; }
        public void setEndDate(String endDate) { this.endDate = endDate; }
    }

    public static class PositionConverter implements Converter {
        public boolean canConvert(Class type) { return type.equals(Position.class); }
        public void marshal(Object source, HierarchicalStreamWriter writer, MarshallingContext context) {
            Position p = (Position) source;
            writer.startNode("title"); writer.setValue(p.getTitle()); writer.endNode();
            writer.startNode("startDate"); writer.setValue(p.getStartDate()); writer.endNode();
            writer.startNode("endDate"); writer.setValue(p.getEndDate()); writer.endNode();
        }
        public Object unmarshal(HierarchicalStreamReader reader, UnmarshallingContext context) {
            Position p = new Position();
            while (reader.hasMoreChildren()) {
                reader.moveDown();
                String nodeName = reader.getNodeName();
                if ("title".equals(nodeName)) p.setTitle(reader.getValue());
                else if ("startDate".equals(nodeName)) p.setStartDate(reader.getValue());
                else if ("endDate".equals(nodeName)) p.setEndDate(reader.getValue());
                reader.moveUp();
            }
            return p;
        }
    }

    public static void main(String[] args) {
        XStream xstream = new XStream();
        xstream.autodetectAnnotations(true);
        xstream.registerConverter(new PositionConverter());
        final Position position = new Position();
        position.setTitle("The Title");
        position.setStartDate("The Start Date");
        position.setEndDate("The End Date");
        final String xml = xstream.toXML(position);
        System.out.println("Generated XML:");
        System.out.println(xml);
        final Position genPosition = (Position) xstream.fromXML(xml);
        System.out.println("Generated Position:");
        System.out.println("\tTitle: " + genPosition.getTitle());
        System.out.println("\tStart Date: " + genPosition.getStartDate());
        System.out.println("\tEnd Date: " + genPosition.getEndDate());
    }
}

